package com.nextrade.service; import com.nextrade.service.ports.PasswordHasher; import org.springframework.security.crypto.argon2.Argon2PasswordEncoder; public final class Argon2PasswordHasher implements PasswordHasher {private final Argon2PasswordEncoder encoder=new Argon2PasswordEncoder(16,32,1,65536,3);public String hash(String raw){return encoder.encode(raw);}public boolean matches(String raw,String hash){return encoder.matches(raw,hash);}}
